-- No educational content or user accounts are seeded.
create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null check(length(display_name) between 1 and 100), created_at timestamptz not null default now());
create table public.roles (name text primary key check(name in ('ADMIN','TEACHER','STUDENT')));
insert into public.roles values ('ADMIN'),('TEACHER'),('STUDENT');
create table public.user_roles (user_id uuid references public.profiles on delete cascade, role text references public.roles, primary key(user_id,role));
create table public.teacher_student_assignments (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.profiles, student_id uuid not null references public.profiles, unique(teacher_id,student_id), check(teacher_id<>student_id), created_at timestamptz not null default now());
create table public.user_preferences (user_id uuid primary key references public.profiles on delete cascade, language text not null default 'en' check(language in ('en','uz','ru')), theme text not null default 'light' check(theme in ('light','dark')), ai_consent boolean not null default false, updated_at timestamptz not null default now());
create function public.has_role(r text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from user_roles where user_id=auth.uid() and role=r) $$;
create function public.can_review(u uuid) returns boolean language sql stable security definer set search_path=public as $$ select has_role('ADMIN') or (has_role('TEACHER') and exists(select 1 from teacher_student_assignments where teacher_id=auth.uid() and student_id=u)) $$;
create function public.new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin
 insert into profiles(id,display_name) values(new.id,left(coalesce(nullif(new.raw_user_meta_data->>'name',''),split_part(new.email,'@',1),'Student'),100));
 insert into user_roles values(new.id,'STUDENT'); insert into user_preferences(user_id) values(new.id); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.new_user();

create table public.courses (id uuid primary key default gen_random_uuid(), title text not null check(length(title)>0), description text not null default '', status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now());
create table public.course_modules (id uuid primary key default gen_random_uuid(), course_id uuid not null references public.courses on delete cascade, title text not null, position int not null default 0);
create table public.lessons (id uuid primary key default gen_random_uuid(), module_id uuid not null references public.course_modules on delete cascade, title text not null, body text not null default '', video_url text, position int not null default 0, status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now());
create table public.lesson_resources (id uuid primary key default gen_random_uuid(), lesson_id uuid not null references public.lessons on delete cascade, title text not null, storage_path text not null);
create table public.course_enrollments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, course_id uuid not null references public.courses, created_at timestamptz not null default now(), unique(user_id,course_id));
create table public.lesson_progress (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, lesson_id uuid not null references public.lessons, completed_at timestamptz not null default now(), unique(user_id,lesson_id));
create table public.tests (id uuid primary key default gen_random_uuid(), title text not null check(length(title)>0), skill text not null check(skill in ('listening','reading')), variant text not null default 'academic' check(variant in ('academic','general')), duration_seconds int not null check(duration_seconds between 60 and 14400), status text not null default 'draft' check(status in ('draft','published','archived')), band_thresholds jsonb, created_at timestamptz not null default now());
create table public.test_sections (id uuid primary key default gen_random_uuid(), test_id uuid not null references public.tests on delete cascade, title text not null, audio_path text, position int not null default 0);
create table public.passages (id uuid primary key default gen_random_uuid(), section_id uuid not null references public.test_sections on delete cascade, title text not null default '', body text not null);
create table public.questions (id uuid primary key default gen_random_uuid(), section_id uuid not null references public.test_sections on delete cascade, prompt text not null, kind text not null check(kind in ('text','choice','true_false_not_given','yes_no_not_given','matching','multiple_choice')), position int not null default 0, max_words int check(max_words>0), points int not null default 1 check(points between 1 and 10));
create table public.question_options (id uuid primary key default gen_random_uuid(), question_id uuid not null references public.questions on delete cascade, label text not null, value text not null, unique(question_id,value));
create table public.answer_keys (question_id uuid primary key references public.questions on delete cascade, accepted text[] not null check(cardinality(accepted)>0), explanation text not null default '');
create table public.test_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, test_id uuid not null references public.tests, started_at timestamptz not null default now(), deadline timestamptz not null, submitted_at timestamptz, raw_score int, total_points int, band numeric(2,1), status text not null default 'in_progress' check(status in ('in_progress','submitted')));
create unique index one_open_attempt on public.test_attempts(user_id,test_id) where status='in_progress';
create table public.student_answers (attempt_id uuid references public.test_attempts on delete cascade, question_id uuid references public.questions, answer text not null check(length(answer)<=4000), primary key(attempt_id,question_id));
create table public.writing_tasks (id uuid primary key default gen_random_uuid(), title text not null, prompt text not null, task_number int not null check(task_number in (1,2)), image_path text, duration_seconds int not null default 2400 check(duration_seconds between 60 and 7200), status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now());
create table public.writing_submissions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, task_id uuid not null references public.writing_tasks, body text not null default '' check(length(body)<=50000), created_at timestamptz not null default now(), deadline timestamptz not null, submitted_at timestamptz);
create unique index one_writing_draft on public.writing_submissions(user_id,task_id) where submitted_at is null;
create table public.writing_evaluations (id uuid primary key default gen_random_uuid(), submission_id uuid not null references public.writing_submissions, evaluator_id uuid references public.profiles, source text not null check(source in ('teacher','ai')), band numeric(2,1) not null check(band between 0 and 9 and mod(band*2,1)=0), criteria jsonb not null, feedback text not null, created_at timestamptz not null default now());
create table public.speaking_tasks (id uuid primary key default gen_random_uuid(), title text not null, prompt text not null, part int not null check(part between 1 and 3), preparation_seconds int not null default 60 check(preparation_seconds between 0 and 300), response_seconds int not null default 120 check(response_seconds between 10 and 600), status text not null default 'draft' check(status in ('draft','published','archived')), created_at timestamptz not null default now());
create table public.speaking_recordings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, task_id uuid not null references public.speaking_tasks, storage_path text not null unique, created_at timestamptz not null default now());
create table public.speaking_transcripts (id uuid primary key default gen_random_uuid(), recording_id uuid not null unique references public.speaking_recordings on delete cascade, body text not null, created_at timestamptz not null default now());
create table public.speaking_evaluations (id uuid primary key default gen_random_uuid(), recording_id uuid not null references public.speaking_recordings, evaluator_id uuid references public.profiles, source text not null check(source in ('teacher','ai')), band numeric(2,1) check(band between 0 and 9 and mod(band*2,1)=0), criteria jsonb not null, feedback text not null, created_at timestamptz not null default now(), check(source='teacher' or band is null));
create table public.mock_exams (id uuid primary key default gen_random_uuid(), title text not null, status text not null default 'draft' check(status in ('draft','published','archived')), available_from timestamptz, available_until timestamptz, allow_resume boolean not null default true, created_at timestamptz not null default now(), check(available_until is null or available_from is null or available_until>available_from));
create table public.mock_exam_sections (id uuid primary key default gen_random_uuid(), mock_exam_id uuid not null references public.mock_exams on delete cascade, skill text not null check(skill in ('listening','reading','writing','speaking')), test_id uuid references public.tests, writing_task_id uuid references public.writing_tasks, speaking_task_id uuid references public.speaking_tasks, position int not null check(position>=0), unique(mock_exam_id,test_id), unique(mock_exam_id,writing_task_id), unique(mock_exam_id,speaking_task_id), check((skill in ('listening','reading') and test_id is not null and writing_task_id is null and speaking_task_id is null) or (skill='writing' and writing_task_id is not null and test_id is null and speaking_task_id is null) or (skill='speaking' and speaking_task_id is not null and test_id is null and writing_task_id is null)));
create table public.mock_exam_attempts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, mock_exam_id uuid not null references public.mock_exams, started_at timestamptz not null default now(), submitted_at timestamptz);
create unique index one_open_mock on public.mock_exam_attempts(user_id,mock_exam_id) where submitted_at is null;
create table public.mock_exam_results (id uuid primary key default gen_random_uuid(), attempt_id uuid not null references public.mock_exam_attempts on delete cascade, section_id uuid not null references public.mock_exam_sections, test_attempt_id uuid references public.test_attempts, writing_submission_id uuid references public.writing_submissions, speaking_recording_id uuid references public.speaking_recordings, unique(attempt_id,section_id), check(num_nonnulls(test_attempt_id,writing_submission_id,speaking_recording_id)=1));
create table public.student_onboarding (user_id uuid primary key references public.profiles on delete cascade, motivation text check(motivation in ('study_abroad','university','career','immigration','personal','other')), target_band numeric(2,1) check(target_band between 5.5 and 9 and mod(target_band*2,1)=0), current_level text check(current_level in ('beginner','elementary','intermediate','upper_intermediate','advanced','unknown')), priority_skills text[] check(priority_skills <@ array['listening','reading','writing','speaking']::text[]), daily_goal_minutes int check(daily_goal_minutes between 5 and 240), weekly_availability int[] check(weekly_availability <@ array[1,2,3,4,5,6,7]), current_step int not null default 0 check(current_step between 0 and 8), completed boolean not null default false, completed_at timestamptz, updated_at timestamptz not null default now(), check(not completed or (motivation is not null and target_band is not null and current_level is not null and cardinality(priority_skills)>0 and daily_goal_minutes is not null and cardinality(weekly_availability)>0 and completed_at is not null)));
create table public.student_goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, title text not null, due_date date, created_at timestamptz not null default now());
create table public.learning_activity_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, kind text not null check(kind in ('lesson','test','writing','speaking','onboarding')), source_id uuid not null, created_at timestamptz not null default now(), unique(user_id,kind,source_id));
create table public.achievements (id uuid primary key default gen_random_uuid(), code text not null unique, title text not null);
insert into public.achievements(code,title) values('onboarding_complete','Your journey begins');
create table public.student_achievements (user_id uuid references public.profiles on delete cascade, achievement_id uuid references public.achievements, awarded_at timestamptz not null default now(), primary key(user_id,achievement_id));
create table public.learning_streaks (user_id uuid primary key references public.profiles on delete cascade, current_days int not null default 0 check(current_days>=0), last_activity_date date);
create table public.content_publications (id uuid primary key default gen_random_uuid(), entity text not null, entity_id uuid not null, status text not null, actor_id uuid references public.profiles, created_at timestamptz not null default now());
create table public.media_assets (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, bucket text not null check(bucket in ('course-media','speaking')), storage_path text not null unique, mime_type text not null, size_bytes int not null check(size_bytes between 1 and 26214400), created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles, action text not null, entity text not null, entity_id text, created_at timestamptz not null default now());
create table public.platform_settings (id boolean primary key default true check(id), ai_enabled boolean not null default false, ai_daily_user_limit int not null default 2 check(ai_daily_user_limit between 0 and 100), ai_daily_platform_limit int not null default 20 check(ai_daily_platform_limit between 0 and 10000));
insert into public.platform_settings(id) values(true);
create table public.ai_usage_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles, source_id uuid not null, kind text not null check(kind in ('writing','speaking')), status text not null default 'reserved' check(status in ('reserved','succeeded','failed')), model text not null, input_tokens int, output_tokens int, estimated_cost_usd numeric(12,6), created_at timestamptz not null default now());
create table public.assignments (id uuid primary key default gen_random_uuid(), teacher_id uuid not null references public.profiles, student_id uuid not null references public.profiles, title text not null, lesson_id uuid references public.lessons, test_id uuid references public.tests, writing_task_id uuid references public.writing_tasks, speaking_task_id uuid references public.speaking_tasks, due_date date, created_at timestamptz not null default now(), check(num_nonnulls(lesson_id,test_id,writing_task_id,speaking_task_id)=1));
create table public.rate_limit_buckets (key text primary key, window_start timestamptz not null, hits int not null);

-- Policies default-deny. Students never write roles, scores, rewards or audit trails.
do $$ declare t text; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or can_review(id));
create policy preferences_read on public.user_preferences for select to authenticated using(user_id=auth.uid());
create policy preferences_update on public.user_preferences for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy roles_read on public.roles for select to authenticated using(true);
create policy own_roles on public.user_roles for select to authenticated using(user_id=auth.uid() or has_role('ADMIN'));
create policy assignments_admin on public.teacher_student_assignments for all to authenticated using(has_role('ADMIN')) with check(has_role('ADMIN'));
create policy assignments_read on public.teacher_student_assignments for select to authenticated using(teacher_id=auth.uid() or student_id=auth.uid());
create function public.course_visible(c uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from courses where id=c and status='published') $$;
create function public.lesson_visible(l uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from lessons l1 join course_modules m on m.id=l1.module_id where l1.id=l and l1.status='published' and course_visible(m.course_id)) $$;
create function public.test_visible(t uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from tests where id=t and status='published') $$;
do $$ declare t text; begin foreach t in array array['courses','course_modules','lessons','lesson_resources','tests','test_sections','passages','questions','question_options','answer_keys','writing_tasks','speaking_tasks','mock_exams','mock_exam_sections','platform_settings'] loop execute format('create policy admin_manage on public.%I for all to authenticated using(has_role(''ADMIN'')) with check(has_role(''ADMIN''))',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['courses','tests','writing_tasks','speaking_tasks','mock_exams'] loop execute format('create policy published_read on public.%I for select to authenticated using(status=''published'')',t); end loop; end $$;
create policy modules_read on public.course_modules for select to authenticated using(course_visible(course_id));
create policy lessons_read on public.lessons for select to authenticated using(lesson_visible(id));
create policy resources_read on public.lesson_resources for select to authenticated using(lesson_visible(lesson_id));
create policy sections_read on public.test_sections for select to authenticated using(test_visible(test_id));
create policy passages_read on public.passages for select to authenticated using(exists(select 1 from test_sections s where s.id=section_id and test_visible(s.test_id)));
create policy questions_read on public.questions for select to authenticated using(exists(select 1 from test_sections s where s.id=section_id and test_visible(s.test_id)));
create policy options_read on public.question_options for select to authenticated using(exists(select 1 from questions q join test_sections s on s.id=q.section_id where q.id=question_id and test_visible(s.test_id)));
create policy mock_sections_read on public.mock_exam_sections for select to authenticated using(exists(select 1 from mock_exams m where m.id=mock_exam_id and m.status='published'));
do $$ declare t text; begin foreach t in array array['course_enrollments','lesson_progress','test_attempts','writing_submissions','speaking_recordings','mock_exam_attempts','learning_activity_events','student_achievements','learning_streaks','ai_usage_logs'] loop execute format('create policy owner_review_read on public.%I for select to authenticated using(user_id=auth.uid() or can_review(user_id))',t); end loop; end $$;
create policy answers_read on public.student_answers for select to authenticated using(exists(select 1 from test_attempts a where a.id=attempt_id and (a.user_id=auth.uid() or can_review(a.user_id))));
create policy mock_results_read on public.mock_exam_results for select to authenticated using(exists(select 1 from mock_exam_attempts a where a.id=attempt_id and (a.user_id=auth.uid() or can_review(a.user_id))));
create policy writing_eval_read on public.writing_evaluations for select to authenticated using(exists(select 1 from writing_submissions s where s.id=submission_id and (s.user_id=auth.uid() or can_review(s.user_id))));
create policy speaking_eval_read on public.speaking_evaluations for select to authenticated using(exists(select 1 from speaking_recordings s where s.id=recording_id and (s.user_id=auth.uid() or can_review(s.user_id))));
create policy transcripts_read on public.speaking_transcripts for select to authenticated using(exists(select 1 from speaking_recordings s where s.id=recording_id and (s.user_id=auth.uid() or can_review(s.user_id))));
create policy onboarding_read on public.student_onboarding for select to authenticated using(user_id=auth.uid() or can_review(user_id));
create policy goals_manage on public.student_goals for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy achievements_read on public.achievements for select to authenticated using(true);
create policy publications_read on public.content_publications for select to authenticated using(has_role('ADMIN'));
create policy audit_read on public.audit_logs for select to authenticated using(has_role('ADMIN'));
create policy media_read on public.media_assets for select to authenticated using(user_id=auth.uid() or has_role('ADMIN'));
create policy assignment_read on public.assignments for select to authenticated using(student_id=auth.uid() or teacher_id=auth.uid() or has_role('ADMIN'));
create policy assignment_write on public.assignments for all to authenticated using(can_review(student_id)) with check(can_review(student_id) and teacher_id=auth.uid());

-- Index every FK used for policy checks and joins.
do $$ declare r record; begin for r in select t.relname as tab, a.attname as col from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace join pg_attribute a on a.attrelid=t.oid and a.attnum=any(c.conkey) where c.contype='f' and n.nspname='public' loop execute format('create index if not exists %I on public.%I(%I)', r.tab||'_'||r.col||'_idx',r.tab,r.col); end loop; end $$;
create index ai_usage_daily on public.ai_usage_logs(created_at,user_id);
